class Solution {
public:
    int minimumRightShifts(vector<int>& nums) {
        int n = nums.size(), drop = -1;
        for (int i = 0; i < n - 1; i++) {
            if (nums[i] > nums[i + 1]) {
                if (drop != -1) return -1;
                drop = i;
            }
        }
        if (drop == -1) return 0;
        if (nums.back() > nums[0]) return -1;
        return n - 1 - drop;
    }
};

class Solution {
    public int minimumRightShifts(List<Integer> nums) {
        int n = nums.size(), drop = -1;
        for (int i = 0; i < n - 1; i++) {
            if (nums.get(i) > nums.get(i + 1)) {
                if (drop != -1) return -1;
                drop = i;
            }
        }
        if (drop == -1) return 0;
        if (nums.get(n - 1) > nums.get(0)) return -1;
        return n - 1 - drop;
    }
}

/**
 * @param {number[]} nums
 * @return {number}
 */
var minimumRightShifts = function(nums) {
    const n = nums.length;
    let drop = -1;
    for (let i = 0; i < n - 1; i++) {
        if (nums[i] > nums[i + 1]) {
            if (drop !== -1) return -1;
            drop = i;
        }
    }
    if (drop === -1) return 0;
    if (nums[n - 1] > nums[0]) return -1;
    return n - 1 - drop;
};
